import numpy as np
from scipy.optimize import minimize

def check_condition(y, D):
    N = len(y)
    for n in range(1, N):
        for m in range(n):
            if abs(y[n] - y[m]) < D / (m + 1 + n + 1):
                return False
    return True

def objective(y, D):
    N = len(y)
    penalty = 0
    for n in range(1, N):
        for m in range(n):
            diff = abs(y[n] - y[m]) - D / (m + 1 + n + 1)
            if diff < 0:
                penalty += diff**2
    return penalty

def find_max_D(N, L=1.0):
    # Binary search for D
    low = 0.0
    high = 10.0 * L # Start with a large upper bound
    for _ in range(20):
        mid = (low + high) / 2
        # Try to find y that satisfies the condition for mid
        # Use multiple random starts for the optimizer
        found = False
        for _ in range(10):
            y0 = np.random.uniform(0, L, N)
            res = minimize(objective, y0, args=(mid,), bounds=[(0, L)]*N, method='L-BFGS-B')
            if res.fun < 1e-7:
                found = True
                break
        if found:
            low = mid
        else:
            high = mid
    return low

