import numpy as np

def check_D(N, D, L=1.0):
    # Try random search with a simple hill-climbing
    for _ in range(100):
        y = np.random.uniform(0, L, N)
        for _ in range(100):
            # Find the pair (m, n) that violates the condition the most
            worst_m, worst_n = -1, -1
            min_diff = float('inf')
            for n in range(1, N):
                for m in range(n):
                    diff = abs(y[n] - y[m]) - D / (m + 1 + n + 1)
                    if diff < min_diff:
                        min_diff = diff
                        worst_m, worst_n = m, n

            if min_diff >= 0:
                return True

            # Move y[worst_n] or y[worst_m] to fix the violation
            # This is a very simple heuristic
            if np.random.rand() < 0.5:
                y[worst_n] += np.random.uniform(-0.1, 0.1)
            else:
                y[worst_m] += np.random.uniform(-0.1, 0.1)
            y = np.clip(y, 0, L)
    return False

