import numpy as np

def greedy_search(N, D, L=1.0):
    y = np.zeros(N)
    y[0] = np.random.uniform(0, L)
    for n in range(1, N):
        forbidden = []
        for m in range(n):
            forbidden.append((y[m] - D / (m + 1 + n + 1), y[m] + D / (m + 1 + n + 1)))
        found = False
        for _ in range(1000):
            p = np.random.uniform(0, L)
            if all(p < low or p > high for low, high in forbidden):
                y[n] = p
                found = True
                break
        if not found:
            return False
    return True

